const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const reykjavik = ee.Geometry.Point([-21.9, 64.15]).buffer(5000); // 5km buffer around city center
  const snaefellsnes = ee.Geometry.Point([-23.5, 64.8]).buffer(5000); // 5km buffer in peninsula

  // 2. Load VIIRS nighttime lights for 2016
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate('2016-01-01', '2016-12-31')
    .select('avg_rad');

  // Check if collection has data
  const count = viirs.size().getInfo();
  console.log(`VIIRS images in 2016: ${count}`);

  if (count === 0) {
    console.log("No VIIRS data for 2016");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate mean composite for 2016
  const meanImage = viirs.mean();

  // 4. Calculate statistics for Reykjavík
  const reykjavikStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: reykjavik,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const reykjavikMean = reykjavikStats.avg_rad_mean;
  const reykjavikCount = reykjavikStats.avg_rad_count;

  console.log(`Reykjavík - Mean: ${reykjavikMean}, Pixels: ${reykjavikCount}`);

  // 5. Calculate statistics for Snæfellsnes
  const snaefellsnesStats = meanImage.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: snaefellsnes,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const snaefellsnesMean = snaefellsnesStats.avg_rad_mean;
  const snaefellsnesCount = snaefellsnesStats.avg_rad_count;

  console.log(`Snæfellsnes - Mean: ${snaefellsnesMean}, Pixels: ${snaefellsnesCount}`);

  // 6. Validation and answer
  if (reykjavikCount === 0 || snaefellsnesCount === 0) {
    console.log("No valid pixels in one or both regions");
    console.log("<answer>C2</answer>");
    return;
  }

  if (reykjavikMean === null || reykjavikMean === undefined || 
      snaefellsnesMean === null || snaefellsnesMean === undefined ||
      isNaN(reykjavikMean) || isNaN(snaefellsnesMean)) {
    console.log("Calculation failed - invalid results");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values
  console.log(`Difference: ${(reykjavikMean - snaefellsnesMean).toFixed(4)}`);

  if (reykjavikMean > snaefellsnesMean) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
